#include <vector>

class Solution {
public:
    bool isTrionic(std::vector<int>& nums) {
        int n = nums.size();
        if (n < 4) return false;

        int i = 0;
        while (i + 1 < n && nums[i] < nums[i + 1]) i++;
        if (i == 0 || i >= n - 2) return false;

        int p = i;
        while (i + 1 < n && nums[i] > nums[i + 1]) i++;
        if (i == p || i >= n - 1) return false;

        while (i + 1 < n && nums[i] < nums[i + 1]) i++;
        return i == n - 1;
    }
};

